import { useFetcher } from "@kasperrt/smolter/react";
import type { clientLoader } from "../tasks.$id/loader";

export default function TaskPreview() {
  const preview = useFetcher<typeof clientLoader>();
  const busy = preview.state !== "idle";

  return (
    <section aria-busy={busy}>
      <button onClick={() => preview.load("/tasks/42")} disabled={busy}>
        Preview task
      </button>
      {preview.data && <p>{preview.data.title}</p>}
      {preview.error && <p role="alert">{preview.error.message}</p>}
    </section>
  );
}

const search = useFetcher<typeof clientLoader>();

return (
  <section>
    <search.Form action="/tasks/search" method="get">
      <label>Query <input name="q" /></label>
      <button>Find tasks</button>
    </search.Form>
    {search.data?.results.map((task) => <p key={task.id}>{task.title}</p>)}
  </section>
);

